fn validate_input(n: Int) -> Result[Int, Str] {
  if n <= 0 { return Err("must be positive"); }
  return Ok(n);
}

fn ensure_even(n: Int) -> Result[Int, Str] {
  if n % 2 != 0 { return Err("must be even"); }
  return Ok(n);
}

fn compute(n: Int) -> Result[Int, Str] {
  return validate_input(n)
    .and_then(|x| ensure_even(x))
    .map(|x| x * x);
}

fn main() -> Int {
  match compute(4) {
    Ok(val) => { return val; }
    Err(_) => { return 0; }
  }
}
